import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BLmRAsdY.js";var i=JSON.parse(`{"title":"请求抽象","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/request.md","filePath":"zh-Hans/deep-dive/request.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/request.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="请求抽象" tabindex="-1">请求抽象 <a class="header-anchor" href="#请求抽象" aria-label="Permalink to “请求抽象”">​</a></h1><p>Sync Engine 暴露两个带类型的请求函数：</p><ul><li><code>Request</code> 负责远端 HTTP 操作</li><li><code>VaultRequest</code> 负责本地 Obsidian vault 操作</li></ul><p>两者都是返回 promise 的函数对象。它们在文件系统实现与底层平台 API 之间提供一个小的、对中间件友好的边界。</p><h2 id="request" tabindex="-1">Request <a class="header-anchor" href="#request" aria-label="Permalink to “Request”">​</a></h2><p><code>Request</code> 定义于 <code>packages/plugin/src/modules/Registrar.ts</code>：</p><div class="language-ts" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Request</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">url</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">params</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> RequestParam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">RequestResponse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span></code></pre></div><p><code>RequestParam</code> 遵循 Obsidian 的 <code>RequestUrlParam</code>，除了 <code>body</code> 使用项目的 <code>Binary</code>（<code>Uint8Array</code>）而不是 Obsidian 原始 API 的 <code>ArrayBuffer</code>，且 <code>url</code> 从参数移到第一个实参。省略 <code>params</code> 对该 URL 执行普通的 <code>GET</code>。</p><p><code>RequestResponse</code> 是 SDK 导出的类型，描述 <code>Request</code> 返回的响应。</p><h3 id="实现" tabindex="-1">实现 <a class="header-anchor" href="#实现" aria-label="Permalink to “实现”">​</a></h3><p>基础实现：</p><ol><li>把 <code>Uint8Array</code> body 转换为 <code>ArrayBuffer</code>。</li><li>调用 Obsidian 的 <code>requestUrl()</code>。</li><li>把结果包装为： <ul><li><code>status</code>：HTTP 状态码</li><li><code>headers</code>：响应头</li><li><code>text()</code>：响应文本</li><li><code>json()</code>：解析后的 JSON</li><li><code>bytes()</code>：响应 <code>ArrayBuffer</code> 转换为 <code>Binary</code></li></ul></li></ol><p>远端文件系统模块从 context 接收 <code>getRequest()</code>，而不是直接拿到底层函数。<code>Registrar</code> 在返回之前按优先级顺序应用已注册的远端请求中间件。因此每个远端 FS 操作都通过同一个抽象完成认证、请求头、重试、速率限制和取消。</p><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to “限制”">​</a></h3><ul><li>Obsidian 的 <code>requestUrl()</code> 只接受完整的字符串或 <code>ArrayBuffer</code> body。<code>Request</code> 无法上传 <code>ReadableStream</code>。</li><li><code>requestUrl()</code> 不通过这个抽象暴露响应体流。<code>bytes()</code> 会物化完整响应。</li><li>流式远端读取必须在 <code>Request</code> 之上实现，通常用多个 range 请求。流式写入必须使用后端专属的分片上传协议。</li><li>HTTP 状态 <code>400</code> 及以上时，请求错误通常由 <code>requestUrl()</code> 抛出。重试行为属于请求中间件，不属于这个基础实现。</li></ul><h2 id="vault-request" tabindex="-1">Vault Request <a class="header-anchor" href="#vault-request" aria-label="Permalink to “Vault Request”">​</a></h2><p><code>VaultRequest</code> 是 <code>VaultFs</code> 使用的本地对应版本，聪明地利用 Obsidian vault 缓存提升性能。它是一个可辨识联合的操作函数：</p><div class="language-ts" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> VaultRequest</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> extends</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> VaultRequestParam</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">method</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;GET&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }&gt;(</span></span>
<span class="line"><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">  key</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">  params</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VaultRequestResponseMap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;method&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]&gt;;</span></span></code></pre></div><p>支持的方法是 <code>GET</code>、<code>GET_STREAM</code>、<code>PUT</code>、<code>APPEND</code>、<code>DELETE</code>、<code>MOVE</code>、<code>MKDIR</code>、<code>EXISTS</code>、<code>STAT</code> 和 <code>LIST</code>。方法同时决定必需参数和响应类型。</p><p><code>createVaultRequest(app)</code> 捕获 <code>app.vault</code>、它的 <code>DataAdapter</code> 和 <code>app.workspace</code>。<code>Registrar</code> 在把函数注入 <code>VaultFs</code> 之前应用本地请求中间件。</p><h3 id="路径转换" tabindex="-1">路径转换 <a class="header-anchor" href="#路径转换" aria-label="Permalink to “路径转换”">​</a></h3><p>请求键使用<a href="./file-system#统一键模式">统一文件系统键模式</a>。</p><p>调用适配器之前，<code>VaultRequest</code> 从每个非根路径移除尾部斜杠，因为 Obsidian 路径不使用文件夹斜杠。<code>LIST</code> 把返回的文件夹路径转换回统一形式。</p><h3 id="操作映射" tabindex="-1">操作映射 <a class="header-anchor" href="#操作映射" aria-label="Permalink to “操作映射”">​</a></h3><ul><li><code>GET</code>：<code>adapter.readBinary()</code>，转换为 <code>Binary</code>。</li><li><code>GET_STREAM</code>：需要文件 <code>size</code>。在 iOS/iPadOS 上，文件通过多个 range 的 <code>fetch</code> <code>GET</code> 请求流式读取，因为 Capacitor 5 只对媒体扩展名支持 ranged 本地文件请求。非媒体文件先复制为 <code>.trash/&lt;random-UUID&gt;.mov</code> 伪装成媒体文件，需要时创建 <code>.trash</code>；流完成、出错或取消后删除副本。其他平台获取 <code>adapter.getResourcePath(path)</code> 并返回 <code>response.body</code>；没有 body 时抛出异常。</li><li><code>PUT</code>：<code>adapter.writeBinary()</code>，把 <code>Binary</code> 转换为 <code>ArrayBuffer</code> 并转发可选的 <code>mtime</code>/<code>ctime</code> 头。</li><li><code>APPEND</code>：<code>adapter.appendBinary()</code>，使用相同的转换和头。</li><li><code>DELETE</code>：按用户垃圾桶选项调用 <code>adapter.remove()</code>、<code>adapter.trashLocal()</code>、<code>adapter.trashSystem()</code>。</li><li><code>MOVE</code>：<code>adapter.rename()</code> 到规范化后的目标路径。</li><li><code>MKDIR</code>：调用 <code>adapter.mkdir()</code>。创建 <code>/</code> 是无操作。</li><li><code>EXISTS</code>：先检查 <code>vault.getAbstractFileByPath()</code>，然后回退到 <code>adapter.exists(path, true)</code>。</li><li><code>STAT</code>：返回一个 Obsidian <code>Stat</code> 类型的状态对象；启用 <code>cached</code> 时，<code>workspace.layoutReady</code> 使用缓存的 <code>TFile</code>/<code>TFolder</code> 对象，否则回退到 <code>adapter.stat()</code>。</li><li><code>LIST</code>：启用 <code>cached</code> 时，布局就绪且键不是 <code>/</code> 时使用缓存的 <code>TFolder.children</code>；否则用 <code>adapter.list()</code>。文件夹结果以尾部斜杠规范化。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to “边界”">​</a></h2><p><code>Request</code> 抽象 HTTP 传输；<code>VaultRequest</code> 抽象 vault 适配器访问。两者都不执行文件系统策略，例如重试、内存控制、路径压平或取消。这些行为由对应的中间件和 FS 包装器提供。</p>`,27)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};